const fs=require('fs'),vm=require('vm'),assert=require('assert');const d=JSON.parse(fs.readFileSync(__dirname+'/live85_data.json'));const ids=['percentiles','holderStatus','holders','eventStatus','events','missing'];const el=Object.fromEntries(ids.map(k=>[k,{}]));const env={window:{},document:{getElementById(k){assert(ids.includes(k));return el[k]}}};vm.createContext(env);vm.runInContext(fs.readFileSync(__dirname+'/modules85.js','utf8'),env);let secondary=0,catalysts=0,themes=0,financial=0;for(const s of d.stocks){assert.equal(s.pricePosition85.symbol,s.symbol);assert.equal(s.ownership85.symbol,s.symbol);assert.equal(s.industryCatalyst85.symbol,s.symbol);env.window.renderResearchModules(s);assert(el.percentiles.innerHTML.includes('不是盘中现价'));assert(el.holders.innerHTML.includes('不是筹码成本分布'));if(s.ownership85.source_grade==='SECONDARY_VENDOR_NOT_PRIMARY_VERIFIED'){secondary++;assert(el.holderStatus.textContent.includes('二级来源'))}if(s.industryCatalyst85.catalysts.length){catalysts++;assert(el.events.innerHTML.includes('韭研D27'))}if(s.industryCatalyst85.shortxia_themes.length){themes++;assert(el.events.innerHTML.includes('2026-10-26'))}if(s.industryCatalyst85.financial)financial++;}const sh=d.stocks.find(s=>s.symbol==='301686.SZ');env.window.renderResearchModules(sh);assert(el.percentiles.innerHTML.includes('实际N=19'));assert(el.percentiles.innerHTML.includes('短历史'));assert(el.holders.innerHTML.includes('季环比 UNKNOWN%'));assert(!el.holders.innerHTML.includes('季环比 0.00%'));assert(el.holders.innerHTML.includes('2026-06-30'));assert(el.holders.innerHTML.includes('2025-12-31'));const zero=JSON.parse(JSON.stringify(sh));zero.ownership85.quarter_change_pct=0;env.window.renderResearchModules(zero);assert(el.holders.innerHTML.includes('季环比 0.00%'));console.log(JSON.stringify({result:'PASS',scope:'VM module rendering not browser',stocks:85,symbol_joins:255,secondary,catalysts,themes,financial,short19:true,null_not_zero:true,quarter_date_visible:true}));
